return {
  json: {
    ...$json,
    threadId: String($json.thread_id ?? ''),
    groupName: String($json.group_name ?? ''),
    senderId: String($json.sender_id ?? ''),
    senderName: String($json.sender_name ?? ''),
    messageText: String($json.message_text ?? ''),
    messageTs: String($json.message_ts ?? ''),
  },
};

const cleanText = (value) => String(value ?? '').trim();
const titleCase = (value) => cleanText(value)
  .toLowerCase()
  .split(/\s+/)
  .filter(Boolean)
  .map((part) => part.charAt(0).toUpperCase() + part.slice(1))
  .join(' ');
const unique = (values) => [...new Set((Array.isArray(values) ? values : []).map(cleanText).filter(Boolean))];
const parseDateFromMessage = (messageText) => {
  const text = cleanText(messageText);
  let match = text.match(/(\d{4})-(\d{2})-(\d{2})/);
  if (match) return `${match[1]}-${match[2]}-${match[3]}`;
  match = text.match(/(\d{1,2})\/(\d{1,2})\/(\d{4})/);
  if (!match) return '';
  return `${match[3]}-${match[2].padStart(2, '0')}-${match[1].padStart(2, '0')}`;
};
const parseShiftFromMessage = (messageText) => {
  const text = cleanText(messageText).toLowerCase();
  if (/\b(buổi|ca)\b[\s.:_-]*(sáng|sang)\b/.test(text)) return 'Sáng';
  if (/\b(buổi|ca)\b[\s.:_-]*(chiều|chieu)\b/.test(text)) return 'Chiều';
  if (/\b(buổi|ca)\b[\s.:_-]*(tối|toi|đêm|dem|ngày|ngay)\b/.test(text)) return 'Cả ngày';
  return '';
};
const parseSiteFromMessage = (messageText) => {
  const lines = cleanText(messageText).split(/\r?\n/).map((line) => cleanText(line)).filter(Boolean);
  if (!lines.length) return '';
  const first = lines[0]
    .replace(/^c(t|ông\s*tr(ì|i)nh)\s*/i, '')
    .replace(/^ct\s*/i, '')
    .replace(/[:.-]+$/g, '')
    .trim();
  return titleCase(first);
};
const splitWorkerAndTask = (rawValue) => {
  const raw = cleanText(rawValue).replace(/[.]+$/g, '').trim();
  if (!raw) return { workersPart: '', task: '' };
  const taskPattern = /\b((t(ầng|ang)|l(ầu|au)|sàn|khu|phòng|p\.?|mặt\s*bằng)\s*\d+[a-zA-Z0-9-]*)\s*$/i;
  const taskMatch = raw.match(taskPattern);
  if (!taskMatch) return { workersPart: raw, task: '' };
  let workersPart = cleanText(raw.slice(0, taskMatch.index));
  workersPart = workersPart.replace(/[,-:]+$/g, '').trim();
  return { workersPart, task: titleCase(taskMatch[1]) };
};
const parseWorkerEntries = (messageText) => {
  const lines = cleanText(messageText).split(/\r?\n/).map((line) => cleanText(line)).filter(Boolean);
  const entries = [];
  for (const line of lines) {
    const numbered = line.match(/^\d+[.)]\s*(.+)$/);
    if (!numbered) continue;
    const { workersPart, task } = splitWorkerAndTask(numbered[1]);
    const workers = unique(workersPart.split(/[;,]/).map((part) => titleCase(part.replace(/^[-•]+/, '').replace(/\.+$/g, '').trim())));
    for (const worker of workers) {
      entries.push({ employee_name: worker, task });
    }
  }
  return entries;
};
const buildLocalFastPath = (messageText) => {
  const text = cleanText(messageText);
  if (!/^\s*(ct|công\s*trình)/im.test(text)) return null;
  if (!/^\s*\d+[.)]\s*\S+/m.test(text)) return null;
  const workDate = parseDateFromMessage(text);
  const shift = parseShiftFromMessage(text);
  const site = parseSiteFromMessage(text);
  const workerEntries = parseWorkerEntries(text);
  if (!workDate || !shift || !site || !workerEntries.length) return null;
  const hours = shift === 'Cả ngày' ? 1 : 0.5;
  const attendanceEntries = workerEntries.map((entry) => ({
    employee_name: entry.employee_name,
    work_date: workDate,
    shift,
    start_time: '',
    end_time: '',
    hours,
    overtime_hours: 0,
    site,
    task: entry.task || '',
    status: 'present',
    note: '',
  }));
  const tasks = unique(attendanceEntries.map((entry) => entry.task));
  const taskText = tasks.length === 1 ? `, hạng mục ${tasks[0]}` : '';
  return {
    action: 'save_attendance',
    question: '',
    summary: `Chấm công công trình ${site} ngày ${workDate} buổi ${shift.toLowerCase()} cho ${attendanceEntries.length} nhân công${taskText}.`,
    document_type: 'attendance',
    confidence: 0.99,
    needs_human_review: false,
    attendance_entries: attendanceEntries,
    notes: ['Đã dùng fast-path cục bộ ngay trong workflow.'],
  };
};
const buildFallbackAnalysis = (messageText, errorLike) => {
  const text = cleanText(messageText);
  const attendanceLike = /\b(ch[aă]m\s*c[oô]ng|ca|buổi|công\s*trình|\bct\b|tầng|lầu|ngày|sáng|chiều)\b/i.test(text);
  return {
    action: attendanceLike ? 'ask_clarification' : 'ignore',
    question: attendanceLike ? 'Mình đang xử lý chậm ở bước hiểu ngữ cảnh. Bạn gửi lại giúp mình theo mẫu: Công trình + Ngày + Buổi + danh sách nhân sự nhé.' : '',
    summary: attendanceLike ? 'OpenClaw chậm hoặc timeout, đã chuyển phiên này sang hỏi lại để không chặn hàng đợi.' : 'Bỏ qua tin nhắn không đủ ngữ cảnh.',
    document_type: attendanceLike ? 'attendance' : 'other',
    confidence: 0.2,
    needs_human_review: attendanceLike,
    attendance_entries: [],
    notes: [
      `OpenClaw unavailable: ${cleanText(errorLike?.message ?? errorLike) || 'unknown error'}`,
      'Đã fallback để tránh block hàng đợi.',
    ],
  };
};
const messageText = String($json.messageText ?? '').trim();
const localFastPath = buildLocalFastPath(messageText);
if (localFastPath) {
  const text = JSON.stringify(localFastPath);
  return {
    json: {
      ...$json,
      content: { parts: [{ text }] },
      finishReason: 'STOP',
      usageMetadata: null,
      ai_provider: 'local-fast-path',
      ai_model: 'rule-parser',
      openclaw_session_id: String($json.threadId ?? ''),
    },
  };
}
const contextUrl = String($env.OPENCLAW_CONTEXT_URL ?? 'http://127.0.0.1:20129/analyze').trim();
let response;
try {
  response = await helpers.httpRequest({
    method: 'POST',
    url: contextUrl,
    headers: { 'Content-Type': 'application/json' },
    body: {
      thread_id: $json.threadId,
      group_name: $json.groupName,
      sender_id: $json.senderId,
      sender_name: $json.senderName,
      message_text: $json.messageText,
      message_ts: $json.messageTs,
    },
    json: true,
    timeout: Number($env.OPENCLAW_CONTEXT_TIMEOUT_MS ?? 15000),
  });
} catch (error) {
  const analysis = buildFallbackAnalysis(messageText, error);
  const text = JSON.stringify(analysis);
  return {
    json: {
      ...$json,
      content: { parts: [{ text }] },
      finishReason: 'ERROR',
      usageMetadata: null,
      ai_provider: 'openclaw-fallback',
      ai_model: 'local-fallback',
      openclaw_session_id: String($json.threadId ?? ''),
    },
  };
}
if (!response?.ok || !response?.analysis) {
  const analysis = buildFallbackAnalysis(messageText, response?.error ?? 'No analysis returned.');
  const text = JSON.stringify(analysis);
  return {
    json: {
      ...$json,
      content: { parts: [{ text }] },
      finishReason: 'ERROR',
      usageMetadata: null,
      ai_provider: 'openclaw-fallback',
      ai_model: 'local-fallback',
      openclaw_session_id: String(response?.session_id ?? $json.threadId ?? ''),
    },
  };
}
const text = JSON.stringify(response.analysis);
return {
  json: {
    ...$json,
    content: { parts: [{ text }] },
    finishReason: 'STOP',
    usageMetadata: null,
    ai_provider: response?.meta?.provider || 'openclaw',
    ai_model: response?.meta?.model || 'gpt-5.4',
    openclaw_session_id: String(response?.session_id ?? ''),
  },
};

const normalizeText = (value) => String(value ?? '').trim();
const normalizeNumber = (value) => {
  const num = Number(value ?? 0);
  return Number.isFinite(num) ? num : 0;
};
const normalizeDate = (value) => {
  const text = normalizeText(value);
  return /^\d{4}-\d{2}-\d{2}$/.test(text) ? text : '';
};
const normalizeTime = (value) => {
  const text = normalizeText(value);
  return /^\d{2}:\d{2}$/.test(text) ? text : '';
};
const asArray = (value) => Array.isArray(value) ? value : [];
const uniq = (values) => [...new Set(values.filter(Boolean))];
const titleCase = (value) => normalizeText(value)
  .toLowerCase()
  .split(/\s+/)
  .filter(Boolean)
  .map((part) => part.charAt(0).toUpperCase() + part.slice(1))
  .join(' ');
const normalizeShiftValue = (value) => {
  const text = normalizeText(value).toLowerCase();
  if (!text) return '';
  if (text.includes('sáng') || text.includes('sang')) return 'Sáng';
  if (text.includes('chiều') || text.includes('chieu')) return 'Chiều';
  if (text.includes('ngày') || text.includes('ngay')) return 'Cả ngày';
  if (text.includes('nửa') || text.includes('nua')) return 'Nửa ngày';
  return titleCase(value);
};

const extractBalancedObject = (text) => {
  const start = text.indexOf('{');
  if (start === -1) return '';
  let depth = 0;
  let inString = false;
  let escaped = false;
  for (let i = start; i < text.length; i += 1) {
    const ch = text[i];
    if (inString) {
      if (escaped) escaped = false;
      else if (ch === '\\') escaped = true;
      else if (ch === '"') inString = false;
      continue;
    }
    if (ch === '"') {
      inString = true;
      continue;
    }
    if (ch === '{') depth += 1;
    else if (ch === '}') {
      depth -= 1;
      if (depth === 0) return text.slice(start, i + 1);
    }
  }
  return '';
};

const parseDateFromMessage = (messageText) => {
  const text = normalizeText(messageText);
  let match = text.match(/(\d{4})-(\d{2})-(\d{2})/);
  if (match) return `${match[1]}-${match[2]}-${match[3]}`;
  match = text.match(/(\d{1,2})\/(\d{1,2})\/(\d{4})/);
  if (!match) return '';
  const day = match[1].padStart(2, '0');
  const month = match[2].padStart(2, '0');
  return `${match[3]}-${month}-${day}`;
};

const parseShiftFromMessage = (messageText) => {
  const text = normalizeText(messageText).toLowerCase();
  if (/\bb(u|ư)\s*o?i?\b[^\n]*\bs(a|á)ng\b/.test(text) || /\bca\s*s(a|á)ng\b/.test(text)) return 'Sáng';
  if (/\bb(u|ư)\s*o?i?\b[^\n]*chi(ề|e)u\b/.test(text) || /\bca\s*chi(ề|e)u\b/.test(text)) return 'Chiều';
  if (/\bca\s*ng(a|à)y\b/.test(text)) return 'Cả ngày';
  return '';
};

const parseSiteFromMessage = (messageText) => {
  const lines = normalizeText(messageText).split(/\r?\n/).map((line) => normalizeText(line)).filter(Boolean);
  if (!lines.length) return '';
  const first = lines[0]
    .replace(/^c(t|ông\s*tr(ì|i)nh)\s*/i, '')
    .replace(/^ct\s*/i, '')
    .replace(/[:.-]+$/g, '')
    .trim();
  return titleCase(first);
};

const parseNamesFromMessage = (messageText) => {
  const lines = normalizeText(messageText).split(/\r?\n/).map((line) => normalizeText(line)).filter(Boolean);
  const names = [];
  for (const line of lines) {
    const numbered = line.match(/^\d+[.)]\s*(.+)$/);
    if (!numbered) continue;
    const parts = numbered[1]
      .split(/[;,]/)
      .map((part) => titleCase(part.replace(/^[-•]+\s*/, '').replace(/\.+$/,'').trim()))
      .filter(Boolean);
    names.push(...parts);
  }
  return uniq(names);
};

const looksLikeStandardAttendance = (messageText) => {
  const lines = normalizeText(messageText).split(/\r?\n/).map((line) => normalizeText(line)).filter(Boolean);
  const hasDate = Boolean(parseDateFromMessage(messageText));
  const hasShift = Boolean(parseShiftFromMessage(messageText));
  const hasSite = Boolean(parseSiteFromMessage(messageText));
  const numberedLines = lines.filter((line) => /^\d+[.)]\s*\S+/.test(line));
  return hasDate && hasShift && hasSite && numberedLines.length > 0;
};

const buildFallbackData = (messageText) => {
  const workDate = parseDateFromMessage(messageText);
  const shift = parseShiftFromMessage(messageText);
  const site = parseSiteFromMessage(messageText);
  const names = parseNamesFromMessage(messageText);
  const attendanceEntries = names.map((employeeName) => ({
    employee_name: employeeName,
    work_date: workDate,
    shift,
    start_time: '',
    end_time: '',
    hours: 0,
    overtime_hours: 0,
    site,
    task: '',
    status: '',
    note: '',
  }));
  return {
    summary: attendanceEntries.length ? `Chấm công ${attendanceEntries.length} người${site ? ` tại ${site}` : ''}.` : '',
    document_type: attendanceEntries.length ? 'attendance' : 'other',
    confidence: attendanceEntries.length ? 0.55 : 0,
    needs_human_review: true,
    attendance_entries: attendanceEntries,
    notes: attendanceEntries.length ? ['AI trả JSON bị cắt, đã fallback từ nội dung tin nhắn gốc.'] : [],
    ambiguity_flags: attendanceEntries.length ? ['malformed_message'] : ['non_attendance'],
    clarification_question: attendanceEntries.length ? 'Mình chưa đọc chắc tin nhắn này. Bạn xác nhận lại giúp mình ngày, ca và danh sách nhân sự nhé?' : '',
  };
};

const messageText = $json.messageText ?? $input.item.json.message_text ?? '';
const finishReason = normalizeText($json?.finishReason);
const parts = $json?.content?.parts ?? [];
const textPart = parts.find((part) => typeof part?.text === 'string')?.text ?? '';
const rawOutput = textPart
  .replace(/^```json\s*/i, '')
  .replace(/^```/i, '')
  .replace(/```$/i, '')
  .trim();

let clean = extractBalancedObject(rawOutput) || rawOutput;
let data;
let usedFallback = false;

try {
  data = JSON.parse(clean);
} catch (error) {
  const fallback = buildFallbackData(messageText);
  if (!fallback.attendance_entries.length) {
    throw new Error(`AI did not return valid JSON. Finish reason: ${finishReason}. Raw output: ${rawOutput}`);
  }
  data = fallback;
  clean = JSON.stringify(fallback);
  usedFallback = true;
}

const seenEntryKeys = new Set();
const attendanceEntries = asArray(data.attendance_entries).map((entry) => ({
  employee_name: titleCase(entry?.employee_name),
  work_date: normalizeDate(entry?.work_date) || parseDateFromMessage(messageText),
  shift: normalizeShiftValue(entry?.shift) || parseShiftFromMessage(messageText),
  start_time: normalizeTime(entry?.start_time),
  end_time: normalizeTime(entry?.end_time),
  hours: normalizeNumber(entry?.hours),
  overtime_hours: normalizeNumber(entry?.overtime_hours),
  site: titleCase(entry?.site || parseSiteFromMessage(messageText)),
  task: titleCase(entry?.task),
  status: normalizeText(entry?.status),
  note: normalizeText(entry?.note),
})).filter((entry) => {
  if (!(entry.employee_name || entry.work_date || entry.site || entry.task || entry.hours || entry.overtime_hours)) return false;
  const dedupeKey = [entry.employee_name.toLowerCase(), entry.work_date, entry.shift.toLowerCase(), entry.site.toLowerCase(), entry.task.toLowerCase()].join('||');
  if (seenEntryKeys.has(dedupeKey)) return false;
  seenEntryKeys.add(dedupeKey);
  return true;
});

const notes = uniq([
  ...asArray(data.notes).map((note) => normalizeText(note)),
  ...(usedFallback ? ['Đã dùng fallback parser từ tin nhắn gốc.'] : []),
  ...(finishReason === 'MAX_TOKENS' ? ['AI bị giới hạn token ở lần chạy này.'] : []),
]).filter(Boolean);

const documentType = normalizeText(data.document_type) || (attendanceEntries.length ? 'attendance' : 'other');
const normalizedConfidence = usedFallback ? Math.min(normalizeNumber(data.confidence || 0.55), 0.7) : normalizeNumber(data.confidence);
let ambiguityFlags = uniq(asArray(data.ambiguity_flags).map((flag) => normalizeText(flag)));

const attendanceCandidate = /\b(ch[aă]m\s*c[oô]ng|ca\s*(s[aá]ng|chi[eề]u|ng[aà]y)|b[uư][oô]i|c[oô]ng\s*tr[iì]nh|ct\b|t[aă]ng\s*ca|n[uử]a\s*ng[aà]y)\b/i.test(messageText);
const standardAttendancePattern = looksLikeStandardAttendance(messageText);
const missingFlags = [];
if (documentType === 'attendance') {
  const hasDate = attendanceEntries.some((entry) => entry.work_date);
  const hasShift = attendanceEntries.some((entry) => entry.shift);
  const hasSite = attendanceEntries.some((entry) => entry.site || entry.task);
  const hasNames = attendanceEntries.some((entry) => entry.employee_name);
  if (!hasDate) missingFlags.push('missing_date');
  if (!hasShift) missingFlags.push('missing_shift');
  if (!hasSite) missingFlags.push('missing_site');
  if (!hasNames) missingFlags.push('unclear_names');
}
let allFlags = uniq([...ambiguityFlags, ...missingFlags]);
if ([/sửa/i, /chỉnh/i, /cập nhật/i, /đính chính/i, /làm lại/i, /bản mới/i].some((rx) => rx.test(messageText)) && !allFlags.includes('duplicate_or_conflicting')) {
  allFlags.push('duplicate_or_conflicting');
}
if (standardAttendancePattern) {
  allFlags = allFlags.filter((flag) => !['unclear_hours', 'unclear_task'].includes(flag));
}

const baseNeedsReview = Boolean(data.needs_human_review) || usedFallback;
const minimumConfidence = standardAttendancePattern ? 0.55 : 0.85;
let needsHumanReview = baseNeedsReview || (documentType === 'attendance' && (normalizedConfidence < minimumConfidence || allFlags.length > 0));
if (standardAttendancePattern && documentType === 'attendance' && attendanceEntries.length > 0 && normalizedConfidence >= minimumConfidence && allFlags.length === 0) {
  needsHumanReview = false;
}
const autoWriteReady = documentType === 'attendance' && attendanceEntries.length > 0 && !needsHumanReview;

const buildClarificationQuestion = () => {
  const provided = normalizeText(data.clarification_question);
  if (provided && !(standardAttendancePattern && ['unclear_hours', 'unclear_task'].some((flag) => ambiguityFlags.includes(flag)))) return provided;
  if (!attendanceCandidate && documentType !== 'attendance') return '';
  const asks = [];
  if (allFlags.includes('duplicate_or_conflicting')) asks.push('đây là bản chốt cuối cùng hay là tin chỉnh sửa');
  if (allFlags.includes('missing_date')) asks.push('ngày chấm công');
  if (allFlags.includes('missing_shift')) asks.push('ca làm việc');
  if (allFlags.includes('missing_site')) asks.push('công trình hoặc hạng mục');
  if (allFlags.includes('unclear_names')) asks.push('danh sách nhân sự');
  if (allFlags.includes('unknown_staff')) asks.push('tên nhân sự đúng theo danh mục');
  if (allFlags.includes('employee_other_shift_same_day') || allFlags.includes('employee_other_site_same_shift') || allFlags.includes('existing_same_scope')) {
    asks.push('xác nhận lại dữ liệu đang xung đột với sheet');
  }
  if (!asks.length) asks.push('nội dung chấm công cần xác nhận lại');
  return `Mình chưa chắc phần ${asks.join(', ')}. Bạn xác nhận lại giúp mình để mình ghi đúng chấm công nhé?`;
};

const clarificationQuestion = buildClarificationQuestion();
let queueStatus = 'ignored';
if (autoWriteReady) queueStatus = 'done';
else if ((documentType === 'attendance' && attendanceEntries.length > 0) || (attendanceCandidate && clarificationQuestion)) queueStatus = 'needs_review';

const summary = normalizeText(data.summary) || (attendanceEntries.length ? `Chấm công ${attendanceEntries.length} người${attendanceEntries[0]?.site ? ` tại ${attendanceEntries[0].site}` : ''}.` : '');

return {
  json: {
    ...$input.item.json,
    finish_reason: finishReason,
    summary,
    document_type: documentType,
    confidence: normalizedConfidence,
    needs_human_review: needsHumanReview,
    auto_write_ready: autoWriteReady,
    attendance_entries: attendanceEntries,
    notes,
    ambiguity_flags: allFlags,
    clarification_question: clarificationQuestion,
    status: queueStatus,
    processed_at: new Date().toISOString(),
    attendance_json: JSON.stringify(attendanceEntries),
    appscript_action: { mode: 'route_attendance', targets: ['ChamCong'] },
    raw_ai_json: clean,
  },
};

const pickQueueFields = (input, overrides = {}) => ({
  id: input.id,
  queue_key: String(input.queue_key ?? ''),
  thread_id: String(input.thread_id ?? ''),
  group_name: String(input.group_name ?? ''),
  sender_id: String(input.sender_id ?? ''),
  sender_name: String(input.sender_name ?? ''),
  message_text: String(input.message_text ?? ''),
  message_ts: String(input.message_ts ?? ''),
  raw_message_json: String(input.raw_message_json ?? ''),
  status: String(input.status ?? 'pending'),
  retry_count: Number(input.retry_count ?? 0),
  last_error: String(input.last_error ?? ''),
  processed_at: input.processed_at ?? null,
  summary: String(input.summary ?? ''),
  attendance_json: String(input.attendance_json ?? ''),
  needs_human_review: Boolean(input.needs_human_review),
  confidence: Number(input.confidence ?? 0),
  appscript_response: String(input.appscript_response ?? ''),
  ...overrides,
});

const url = 'https://script.google.com/macros/s/AKfycbyzC-qw38puhlm5btycJs6ohYXArbRWBF7j70o0zU4MeHCWaoKjXM4BN4XXZXveHsgD/exec';
const clarificationContext = $json.clarificationContext ?? null;
const clarificationResolution = $json.clarification_resolution ?? $json.clarificationResolution ?? null;

const postJson = async (body) => {
  const response = await helpers.httpRequest({
    method: 'POST',
    url,
    headers: { 'Content-Type': 'application/json' },
    body,
    json: false,
  });
  const responseText = typeof response === 'string' ? response : JSON.stringify(response);
  const responseLower = responseText.toLowerCase();
  if (
    responseLower.includes('<!doctype html>') ||
    responseLower.includes('không tìm thấy hàm tập lệnh: dopost') ||
    responseLower.includes('khong tim thay ham tap lenh: dopost')
  ) {
    throw new Error(`Apps Script deployment is invalid or missing doPost. Response: ${responseText}`);
  }
  let parsed;
  try {
    parsed = JSON.parse(responseText);
  } catch (error) {
    throw new Error(`Apps Script did not return valid JSON. Response: ${responseText}`);
  }
  if (!parsed?.ok) {
    throw new Error(`Apps Script returned ok=false. Response: ${responseText}`);
  }
  return { parsed, responseText };
};

if ($json.document_type !== 'attendance' || !Array.isArray($json.attendance_entries) || $json.attendance_entries.length === 0) {
  const shouldAskBack = String($json.status ?? '') === 'needs_review' && String($json.clarification_question ?? '').trim();
  const askPayload = shouldAskBack ? {
    mode: 'clarification_request',
    question: String($json.clarification_question ?? ''),
    ambiguity_flags: Array.isArray($json.ambiguity_flags) ? $json.ambiguity_flags : [],
    notes: Array.isArray($json.notes) ? $json.notes : [],
  } : { skipped: true, reason: 'non-attendance-or-empty' };
  return { json: pickQueueFields($json, { appscript_response: JSON.stringify(askPayload) }) };
}

if (!$json.auto_write_ready) {
  return {
    json: pickQueueFields($json, {
      status: 'needs_review',
      appscript_response: JSON.stringify({
        mode: 'clarification_request',
        question: String($json.clarification_question ?? ''),
        confidence: Number($json.confidence ?? 0),
        ambiguity_flags: Array.isArray($json.ambiguity_flags) ? $json.ambiguity_flags : [],
        notes: Array.isArray($json.notes) ? $json.notes : [],
      }),
    }),
  };
}

const validationPayload = {
  ...$json,
  mode: 'validate_attendance',
  clarification_context: clarificationContext,
  clarification_resolution: clarificationResolution,
};
const { parsed: validationParsed, responseText: validationResponseText } = await postJson(validationPayload);

if (validationParsed.mode !== 'validate_attendance' || typeof validationParsed.valid !== 'boolean') {
  throw new Error(
    `Apps Script validator is outdated or missing validate_attendance mode. Response: ${validationResponseText}`,
  );
}

if (validationParsed.valid === false) {
  const conflictFlags = Array.isArray(validationParsed.conflicts)
    ? validationParsed.conflicts.map((conflict) => String(conflict?.type ?? '')).filter(Boolean)
    : [];
  const mergedFlags = [...new Set([
    ...(Array.isArray($json.ambiguity_flags) ? $json.ambiguity_flags : []),
    ...conflictFlags,
  ])];
  const mergedNotes = [...new Set([
    ...(Array.isArray($json.notes) ? $json.notes : []),
    String(validationParsed.summary ?? '').trim(),
  ].filter(Boolean))];
  return {
    json: pickQueueFields($json, {
      status: 'needs_review',
      needs_human_review: true,
      appscript_response: JSON.stringify({
        mode: 'clarification_request',
        source: 'sheet_validation',
        question: String(validationParsed.clarification_question ?? '').trim() || 'Mình thấy có xung đột với dữ liệu hiện có trong sheet. Bạn xác nhận lại giúp mình nhé?',
        confidence: Number($json.confidence ?? 0),
        ambiguity_flags: mergedFlags,
        notes: mergedNotes,
        conflicts: Array.isArray(validationParsed.conflicts) ? validationParsed.conflicts : [],
        validation: validationParsed,
      }),
    }),
  };
}

const savePayload = {
  ...$json,
  mode: 'route_attendance',
  validation_snapshot: validationParsed,
  clarification_context: clarificationContext,
  clarification_resolution: clarificationResolution,
};
const { responseText: saveResponseText } = await postJson(savePayload);

return {
  json: pickQueueFields($json, {
    appscript_response: saveResponseText,
  }),
};
